input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // --- quote: processing fee and simplest cases ---
  it.todo("quotes an empty item list as 5 G -- only the processing fee");
  it.todo("quotes a plain sword for a 0-year customer as 115 G -- 100 base + 10 first insurance + 5 fee");

  // --- quote: price list per item type (parallel catalogue, one test per entry) ---
  it.todo("quotes a plain amulet for a 0-year customer as 71 G -- 60 base + 6 first insurance + 5 fee");
  it.todo("quotes a plain staff for a 0-year customer as 93 G -- 80 base + 8 first insurance + 5 fee");
  it.todo("quotes a plain potion for a 0-year customer as 49 G -- 40 base + 4 first insurance + 5 fee");
  it.todo("quotes a single rune for a 0-year customer as 33 G -- 25 base + 2.5 first insurance + 5 fee, rounded up");
  it.todo("quotes a single moonstone for a 0-year customer as 33 G -- 25 base + 2.5 first insurance + 5 fee, rounded up");

  // --- quote: component building block of 3 alike components ---
  it.todo("base premium for 2 runes is 50 G -- no block");
  it.todo("base premium for 3 runes is 60 G -- the block applies");
  it.todo("base premium for 4 runes is 100 G -- no block, a block requires exactly 3");
  it.todo("base premium for 7 runes is 175 G -- no block within 7 alike components");
  it.todo("base premium for 2 runes + 1 moonstone is 75 G -- no block, types differ");
  it.todo("base premium for 3 runes + 3 moonstones is 120 G -- two separate blocks");

  // --- quote: item-specific modifiers ---
  it.todo("a cursed sword adds a 50 % curse surcharge to that item's base premium -- 50 G on 100 G");
  it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge -- 30 G on 100 G");
  it.todo("a sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("a cursed sword with enchantment 5 adds both surcharges -- 50 G + 30 G on 100 G");
  it.todo("on a policy with a cursed sword and a plain amulet the curse surcharge is 50 G -- 50 % of the cursed item only, not of the 160 G policy total");

  // --- quote: policy-wide modifiers ---
  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("the 10 % first-insurance surcharge applies on the policy base premium of every quote");
  it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
  it.todo("the first quote in a scenario receives no follow-up contract discount");
  it.todo("policy-wide modifiers apply to the sum of item base premiums, the 5 G fee is added last");

  // --- quote: rounding in MHPCO's favour ---
  it.todo("a premium of 197.5 G is rounded up to 198 G -- rounding favours MHPCO");
  it.todo("intermediate premium amounts stay fractional, only the final premium is rounded");

  // --- quote: integration examples ---
  it.todo("newcomer with a cursed steel sword of enchantment 3 pays 165 G -- 100 + 50 curse + 10 first insurance + 5 fee");
  it.todo("3-year customer's second quote for a cursed steel sword of enchantment 7 pays 160 G -- 100 + 50 + 30 - 20 + 10 - 15 + 5");

  // --- quote: insurance sum and cap ---
  it.todo("a policy of one sword has insurance sum 1000 G and cap 2000 G");
  it.todo("a policy of a sword and an amulet has insurance sum 1600 G and cap 3200 G");
  it.todo("a policy of a sword and 3 runes has insurance sum 1750 G -- the block discount does not lower the insurance sum");
  it.todo("a policy of two swords has insurance sum 2000 G and cap 4000 G");
  it.todo("a cursed sword's cap stays 2000 G -- premium modifiers do not raise the cap");

  // --- claim: deductible and standard reimbursement ---
  it.todo("a steel sword of enchantment 3 damaged by 500 G pays out 400 G -- full reimbursement minus the 100 G deductible");
  it.todo("a rune damaged by 200 G pays out 100 G -- runes have no enchantment or material, so no special clause applies");
  it.todo("the 100 G deductible applies once per damaged item -- 500 G sword + 300 G amulet pays out 600 G");

  // --- claim: special clauses ---
  it.todo("a steel sword of enchantment 9 damaged by 1000 G pays out 400 G -- 50 % high-enchantment clause, then deductible");
  it.todo("a sword of exactly enchantment 8 is reimbursed at 50 % -- the threshold is inclusive");
  it.todo("a dragon-material sword of enchantment 5 damaged by 800 G pays out 700 G -- full reimbursement, then deductible");
  it.todo("a dragon-material sword of enchantment 9 damaged by 1000 G pays out 400 G -- the 50 % rule wins over full reimbursement");
  it.todo("a dragon-material sword of exactly enchantment 8 damaged by 1000 G pays out 400 G");

  // --- claim: cap exhaustion across successive claims ---
  it.todo("a first 1500 G claim on a 1000 G sword policy pays out 1400 G and leaves 600 G of cap");
  it.todo("a second 1500 G claim on the same policy pays out only the remaining 600 G and leaves 0 G of cap");
  it.todo("a claim beyond an exhausted cap pays out 0 G and leaves 0 G of cap");

  // --- claim: multiple items of the same type ---
  it.todo("two sword damage entries against a two-sword policy are two separate damages, each with its own deductible");

  // --- claim: rounding in MHPCO's favour ---
  it.todo("a payout of 350.5 G is rounded down to 350 G -- rounding favours MHPCO");

  // --- claim: never negative ---
  it.todo("a damage of 50 G below the 100 G deductible pays out 0 G, not a negative amount");

  // --- CLI: happy paths ---
  it.todo("the CLI reads a scenario from stdin and writes one result per step to stdout in order");
  it.todo("the CLI writes a quote step result as {premium} and a claim step result as {payout, remainingCap}");
  it.todo("the CLI resolves a claim's policy field as the zero-based index of the quote step that created the policy");
  it.todo("the CLI exits with status 0 on a valid scenario");

  // --- CLI: rejection contract (spec fixes only exit status, stderr, and absent stdout results) ---
  it.todo("a quote with an unknown item type such as broomstick exits non-zero, writes an error to stderr, and writes no results to stdout");
  it.todo("a claim whose damaged item is not part of the policy exits non-zero and writes an error to stderr");
  it.todo("a claim damaging an item of an unknown type exits non-zero and writes an error to stderr");
  it.todo("a claim with more damage entries of a type than the policy covers exits non-zero and rejects the whole claim");
  it.todo("a claim with a negative damage amount of -200 exits non-zero and writes an error to stderr");
});
EOF
pnpm test 2>&1 | tail -15

