python3 - <<'PY'
p='src/claim-office.ts'
s=open(p).read()
s=s.replace('''const PROCESSING_FEE = 5;

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map(() => ({ premium: PROCESSING_FEE }));
}''','''const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

function quotePremium(items: Item[]): number {
  const policyBasePremium = items.reduce(
    (total, item) => total + BASE_PREMIUMS[item.type],
    0,
  );
  const firstInsurance = policyBasePremium * FIRST_INSURANCE_SURCHARGE;

  return policyBasePremium + firstInsurance + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
}''')
open(p,'w').write(s)
