const CAP_FACTOR = 2;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

interface Policy {
  items: Item[];
  remainingCap: number;
}

function insuranceSum(items: Item[]): number {
  return items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
}

function roundPayoutInMHPCOsFavour(payout: number): number {
  return Math.floor(payout);
}

function reimbursementFor(damage: Damage): number {
  return Math.max(damage.amount - DEDUCTIBLE_PER_DAMAGE, 0);
}

function settleClaim(policy: Policy, incident: Incident): StepResult {
  const claimed = incident.damages.reduce(
